<section class="ps-section" aria-labelledby="events-title"><div class="ps-container"><?php ps_heading('events-title',ps_text('मिलना, जुड़ना, आगे बढ़ना','GATHER. CONNECT. PARTICIPATE.'),ps_text('कार्यक्रम और सहभागिता','Around the community.'),'',base_url('/events'),ps_text('सभी कार्यक्रम','All events')); ?><div class="ps-event-groups"><?php foreach([ps_text('आगामी कार्यक्रम','Upcoming events')=>$upcoming,ps_text('हाल के कार्यक्रम','Past events')=>$past] as $label=>$group): ?><div><h3 class="ps-group-title"><?= e($label) ?></h3><?php if(!$group): ?><p class="ps-empty"><?= e(ps_text('नए कार्यक्रम घोषित होने पर यहाँ दिखाई देंगे।','New dates will appear here when announced.')) ?></p><?php endif; foreach(array_slice($group,0,3) as $event): $stamp=strtotime($event['event_date']); ?><article class="ps-event"><time datetime="<?= e($event['event_date']) ?>"><strong><?= date('d',$stamp) ?></strong><span><?= date('M Y',$stamp) ?></span></time><div><span class="ps-eyebrow"><?= e($event['event_date']>$today->format('Y-m-d')?ps_text('आगामी','UPCOMING'):($event['event_date']===$today->format('Y-m-d')?ps_text('आज','TODAY'):ps_text('संपन्न','COMPLETED'))) ?></span><h4 lang="<?= ps_content_lang($event['title']) ?>"><a href="<?= e(base_url('/events/'.$event['slug'])) ?>"><?= e($event['title']) ?></a></h4><?php if(!empty($event['location'])): ?><p lang="<?= ps_content_lang($event['location']) ?>"><i class="fa-solid fa-location-dot" aria-hidden="true"></i> <?= e($event['location']) ?></p><?php endif; ?></div><a class="ps-event-arrow" href="<?= e(base_url('/events/'.$event['slug'])) ?>" aria-label="<?= e($event['title']) ?>">↗</a></article><?php endforeach; ?></div><?php endforeach; ?></div></div></section>
<section class="ps-section ps-literature" aria-labelledby="literature-title"><div class="ps-container ps-literature-grid"><div><span class="ps-eyebrow"><?= e(ps_text('माटी की भाषा, मन की बात','THE LANGUAGE OF OUR ROOTS')) ?></span><h2 id="literature-title"><?= e(ps_text('साहित्य और संस्कृति','Words rooted in culture.')) ?></h2><p><?= e(ps_text('अवधी की आत्मीयता, लोक-संस्कृति की स्मृतियाँ और समाज से संवाद करती रचनाएँ।','The warmth of Awadhi, memories of local culture, and writing in conversation with society.')) ?></p><a class="ps-button ps-button-secondary" href="<?= e(base_url($literature?'/campaigns/'.$literature['slug']:'/blog')) ?>"><?= e(ps_text('अवधी से जुड़ें','Explore Awadhi & culture')) ?> ↗</a></div><div class="ps-literary-art" aria-hidden="true"><span>अ</span><div>अवधी<br>साहित्य · संस्कृति · संवाद</div></div></div></section>
